sysauto_script.script:
(function () {
    // Clear data_real_entrega on ENT0001050 (status is not entregue)
    var gr = new GlideRecord('x_915815_smart_log_entrega');
    if (gr.get('3c1ba59983a2075059d35fd6feaad3c8')) {
        gr.setValue('data_real_entrega', '');
        gr.update();
        gs.info('Data fix: Cleared data_real_entrega on ' + gr.getValue('number'));
    }

    // Set prioridade='media' on records that need it
    var sysIds = [
        '3c1ba59983a2075059d35fd6feaad3c8',
        '119d880d8326435059d35fd6feaad394',
        'ba8e4c8d8326435059d35fd6feaad312'
    ];

    for (var i = 0; i < sysIds.length; i++) {
        var rec = new GlideRecord('x_915815_smart_log_entrega');
        if (rec.get(sysIds[i])) {
            if (!rec.getValue('prioridade')) {
                rec.setValue('prioridade', 'media');
                rec.update();
                gs.info('Data fix: Set prioridade=media on ' + rec.getValue('number'));
            }
        }
    }

    gs.info('One-time data fix completed.');
})();
